package com.zenitrade.service;
import com.zenitrade.entity.*; import com.zenitrade.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import java.math.*;
@Service public class TradeService { public static final BigDecimal BROKERAGE=BigDecimal.valueOf(20); private final CurrentUser cu; private final StockRepository stocks; private final HoldingRepository holdings; private final TradeRepository trades; private final UserRepository users; public TradeService(CurrentUser cu,StockRepository s,HoldingRepository h,TradeRepository t,UserRepository u){this.cu=cu;stocks=s;holdings=h;trades=t;users=u;} @Transactional public Trade execute(String symbol,int qty,String side,String product){if(qty<1)throw new IllegalArgumentException("Quantity must be at least 1");User u=cu.get();Stock st=stocks.findBySymbolIgnoreCase(symbol).orElseThrow(()->new IllegalArgumentException("Stock not found"));BigDecimal value=st.currentPrice.multiply(BigDecimal.valueOf(qty));boolean buy="BUY".equalsIgnoreCase(side);Holding h=holdings.findByUserIdAndStockIdAndProductType(u.id,st.id,product).orElse(null);if(buy){BigDecimal debit=value.add(BROKERAGE);if(u.virtualCash.compareTo(debit)<0)throw new IllegalArgumentException("Insufficient demo funds");u.virtualCash=u.virtualCash.subtract(debit);if(h==null){h=new Holding();h.user=u;h.stock=st;h.productType=product;h.quantity=qty;h.averageBuyPrice=st.currentPrice;}else{BigDecimal old=h.averageBuyPrice.multiply(BigDecimal.valueOf(h.quantity));h.quantity+=qty;h.averageBuyPrice=old.add(value).divide(BigDecimal.valueOf(h.quantity),2,RoundingMode.HALF_UP);}holdings.save(h);}else{if(h==null||h.quantity<qty)throw new IllegalArgumentException("Insufficient shares to sell");u.virtualCash=u.virtualCash.add(value.subtract(BROKERAGE));h.quantity-=qty;if(h.quantity==0)holdings.delete(h);else holdings.save(h);}users.save(u);Trade tr=new Trade();tr.user=u;tr.stock=st;tr.tradeType=buy?"BUY":"SELL";tr.productType=product;tr.quantity=qty;tr.price=st.currentPrice;tr.brokerage=BROKERAGE;tr.totalAmount=buy?value.add(BROKERAGE):value.subtract(BROKERAGE);return trades.save(tr);} }
